  \draw[ink, fill=gold!40] (0.5,0.26) circle (0.17);
  \draw[ink, <->] (-1.42,0) -- (-1.42,1.35);
  \node[left, font=\scriptsize] at (-1.5,0.675) {$h_1$};
  \draw[ink, <->] (1.42,0) -- (1.42,2);
